var e={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Готові до вставки блоки конфігурації Klipper та макроси - стартові послідовності, робота з філаментом, формування вхідного сигналу, мережа столу тощо. Скопіюйте потрібний і вставте у свій printer.cfg (редактор конфігурації - чудове місце для цього).`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Довідка`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Про шаблони конфігурації`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Закрити`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Як користуватися`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Відфільтруйте за категорією, щоб знайти макрос або блок конфігурації.`}},{t:0,b:{t:2,i:[{t:3}],s:`Прочитайте опис і дізнайтеся, які секції потрібні.`}},{t:0,b:{t:2,i:[{t:3}],s:`Скопіюйте шаблон, вставте у свою конфігурацію та налаштуйте значення.`}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:`Що це таке`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Дібраний набір поширених будівельних блоків Klipper: gcode_macros (PRINT_START, PAUSE/RESUME, завантаження/вивантаження філаменту, M600) та секції конфігурації ([input_shaper], [bed_mesh], [firmware_retraction], …). Це відправні точки - прочитайте кожну й налаштуйте під свій принтер.`}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:`Вставлення шаблону`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Скопіюйте шаблон, потім вставте його у свій printer.cfg - сирий перегляд (Raw) у редакторі конфігурації зручне для цього місце. Після збереження перезапуск прошивки застосує зміни. Завжди спершу переглядайте значення; типові значення тут розумні, але не налаштовані під ваш принтер.`}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:`Потрібні секції`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Кожен шаблон перелічує секції конфігурації, які він визначає або від яких залежить. Якщо секція вже існує у вашій конфігурації, об’єднайте ключі замість вставлення дубліката (дубльована секція відхиляється під час запуску).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Глосарій`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:`Шаблон`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Готовий до вставки фрагмент конфігурації Klipper або G-code макросу, який ви копіюєте у printer.cfg.`}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:`gcode_macro`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Іменована команда, яку ви визначаєте в конфігурації (напр. PRINT_START) і яка виконує послідовність G-code.`}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:`Секція`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Блок конфігурації [у квадратних дужках], напр. [bed_mesh] - одиниця, у яку групується конфігурація Klipper.`}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:`Категорія`}},all:{t:0,b:{t:2,i:[{t:3}],s:`Усі категорії`}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:`Копіювати`}},copied:{t:0,b:{t:2,i:[{t:3}],s:`Скопійовано!`}},requires:{t:0,b:{t:2,i:[{t:3,v:`Секції: `},{t:4,k:`sections`}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:`-`}}},count:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` шаблонів`}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Завантаження шаблонів…`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Не вдалося завантажити шаблони.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`У цій категорії немає шаблонів.`}},retry:{t:0,b:{t:2,i:[{t:3}],s:`Повторити`}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:`Блоки конфігурації`}},macros:{t:0,b:{t:2,i:[{t:3}],s:`Макроси`}}}}};export{e as default};